function HistogramFepxVariable(fignum)%%  Free-standing plotting script%% % compute and plot frequency distribution for element values of specified% file variable.%% the pwd should be the directory with the FEpX .sim files   j=fignum; framefilebasename = input('Basename (with extension .h5) of the file with simulation results: ', 's'); framenumber = input('Enter the frame number in the .h5 dataset file to be analyzed: ', 's'); fieldvariablename = input('Field variable name in .h5 file: ', 's'); datapath=['/Frame_' framenumber]; datapath = append(datapath,'/'); datapath = append(datapath,fieldvariablename); datafile2 = h5read([framefilebasename '.h5'],datapath); datasize = size(datafile2); datadim = ndims(datasize); if(datasize(2) >= 2) compdatasize  = datasize(1); fielddatasize = datasize(2); datafile = zeros(fielddatasize,1);    for ifield = 1:1:fielddatasize        elfielddata = datafile2(:,ifield);        datafile(ifield) = norm(elfielddata);    end else compdatasize  = 1; fielddatasize = datasize(1); datafile = datafile2; end meanvalue = mean(datafile2) stdvalue = std(datafile2) maxvalue = max(datafile2) minvalue = min(datafile2) nbins =40    j = j+1;    figure(j)            clf;           axis([minvalue maxvalue 0 0.3]);    hold 'on';      plottitle = 'Grain ', fieldvariablename, ' Distribution';    ab_label = fieldvariablename;        ord_label_left = 'Frequency';    ord_label_right = 'Cumulative Frequency';      key_values = [ '  Mean = ',num2str(meanvalue),';  SD = ',num2str(stdvalue),';  Max = ',num2str(maxvalue)];    yyaxis left;    p0 = histogram(datafile2,nbins,'Normalization','probability','DisplayStyle', 'bar','LineWidth',2.0);    ylabel(ord_label_left,'Fontsize',30);         yyaxis right;    axis([minvalue maxvalue 0 1]);    p1 = histogram(datafile2,'Normalization','cdf','DisplayStyle','stairs','LineWidth',2.0);    ylabel(ord_label_right,'Fontsize',30);      set(gca,'Box','on','LineWidth',2,'FontName','Helvetica','FontSize',24);    xlabel(ab_label);       legend(key_values,'Location','Northwest','FontSize',12);    hold 'off'               